#!/bin/sh
# Builds the engine for Apple's platforms and leaves a Swift package
# around it, here in apple/:
#
#   PrismFFI.xcframework        the Rust library: macOS, iOS, iOS Simulator (arm64)
#   Sources/Prism/prism_ffi.swift   the Swift API, generated by UniFFI
#
# An app depends on the package (`.package(path: "…/prism/apple")`) and
# imports Prism. Both are generated, and neither is checked in: run this
# after the Rust changes.
#
#   apple/build.sh            # build everything
#   apple/build.sh check      # and run the Swift checks: on this Mac, and in a booted simulator if there is one
set -eu
cd "$(dirname "$0")/.."
MODE="${1:-}"
export MACOSX_DEPLOYMENT_TARGET=15.0
export IPHONEOS_DEPLOYMENT_TARGET=18.0

TARGETS="aarch64-apple-darwin aarch64-apple-ios aarch64-apple-ios-sim"
for target in $TARGETS; do
  rustup target list --installed | grep -qx "$target" || rustup target add "$target"
  cargo build --release -p prism-ffi --target "$target"
done

GENERATED=target/apple/generated
HEADERS=target/apple/headers
rm -rf "$GENERATED" "$HEADERS" apple/PrismFFI.xcframework
mkdir -p "$GENERATED" "$HEADERS"
cargo run -q --release -p prism-ffi --bin uniffi-bindgen -- generate \
  --library target/aarch64-apple-darwin/release/libprism_ffi.dylib --language swift --out-dir "$GENERATED"
cp "$GENERATED/prism_ffiFFI.h" "$HEADERS/"
cp "$GENERATED/prism_ffiFFI.modulemap" "$HEADERS/module.modulemap"
cp "$GENERATED/prism_ffi.swift" apple/Sources/Prism/prism_ffi.swift

set --
for target in $TARGETS; do
  set -- "$@" -library "target/$target/release/libprism_ffi.a" -headers "$HEADERS"
done
xcodebuild -create-xcframework "$@" -output apple/PrismFFI.xcframework >/dev/null
echo "built apple/PrismFFI.xcframework and apple/Sources/Prism/prism_ffi.swift"

if [ "$MODE" = check ]; then
  # On this Mac, through the package, as an app would use it.
  (cd apple && swift run -c release PrismChecks)
  # In a simulator, if one is booted: the same checks, built for it.
  booted=$(xcrun simctl list devices booted | sed -n 's/.*(\([0-9A-F-]\{36\}\)) (Booted).*/\1/p' | head -1)
  if [ -n "$booted" ]; then
    sdk=$(xcrun --sdk iphonesimulator --show-sdk-path)
    xcrun --sdk iphonesimulator swiftc -swift-version 5 -O -target arm64-apple-ios18.0-simulator -sdk "$sdk" \
      -I "$HEADERS" -L target/aarch64-apple-ios-sim/release -lprism_ffi -lz -liconv -framework Security -framework CoreFoundation \
      -o target/apple/prism-checks-ios-sim apple/Sources/Prism/prism_ffi.swift crates/prism-ffi/swift/Tests/main.swift
    xcrun simctl spawn "$booted" "$PWD/target/apple/prism-checks-ios-sim"
  else
    echo "no simulator is booted: the checks were not run on iOS"
  fi
fi
